import { getProgramName, parseCliArgs } from './lib/cli.mjs';
import { formatPythonList } from './lib/python-repr.mjs';
import { splitSqlStatements } from './lib/sql-splitter.mjs';

function main() {
  const programName = getProgramName(process.argv[1]);
  const parsed = parseCliArgs(process.argv.slice(2), programName);

  if (parsed.kind === 'help') {
    process.stdout.write(parsed.text);
    return 0;
  }

  if (parsed.kind === 'error') {
    process.stderr.write(parsed.text);
    return parsed.code;
  }

  const result = splitSqlStatements(parsed.value.a);
  process.stdout.write(`${formatPythonList(result)}\n`);
  return 0;
}

process.exit(main());

